contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _log, address _log2) public payable {
        require(_log != address(0));

        bool firstReverted;
        c.SetLogFile(_log); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool secondReverted;
        c.SetLogFile(_log2); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        assert(!firstReverted && secondReverted);
    }

    receive() external payable {}
}

